class APIServerProcessManager:
    """Manages a group of API server processes.

    Handles creation, monitoring, and termination of API server worker
    processes. Also monitors extra processes to check if they are healthy.
    """

    def __init__(
        self,
        target_server_fn: Callable,
        listen_address: str,
        sock: Any,
        args: argparse.Namespace,
        num_servers: int,
        input_addresses: list[str],
        output_addresses: list[str],
        stats_update_address: Optional[str] = None,
    ):
        """Initialize and start API server worker processes.

        Args:
            target_server_fn: Function to call for each API server process

                                   "CoreEngineActorManager"]] = None,
    coordinator: Optional["DPCoordinator"] = None) -> None:
"""Wait for all processes to complete or detect if any fail.

Raises an exception if any process exits with a non-zero status.

Args:
    api_server_manager: The manager for API servers.
    engine_manager: The manager for engine processes.
        If CoreEngineProcManager, it manages local engines;
        if CoreEngineActorManager, it manages all engines.
    coordinator: The coordinator for data parallel.
"""

from vllm.v1.engine.utils import (CoreEngineActorManager,
                                  CoreEngineProcManager)

try:
    logger.info("Waiting for API servers to complete ...")
    # Create a mapping of sentinels to their corresponding processes
    # for efficient lookup
    sentinel_to_proc: dict[Any, BaseProcess] = {
        proc.sentinel: proc
        for proc in api_server_manager.processes
    }

    if coordinator:
        sentinel_to_proc[coordinator.proc.sentinel] = coordinator.proc

    actor_run_refs = []
    if isinstance(engine_manager, CoreEngineProcManager):
        for proc in engine_manager.processes:
            sentinel_to_proc[proc.sentinel] = proc
    elif isinstance(engine_manager, CoreEngineActorManager):
        actor_run_refs = engine_manager.get_run_refs()

    # Check if any process terminates
    while sentinel_to_proc or actor_run_refs:
        # Wait for any process to terminate
        ready_sentinels: list[Any] = connection.wait(sentinel_to_proc,
                                                     timeout=5)

        # Process any terminated processes
        for sentinel in ready_sentinels:
            proc = sentinel_to_proc.pop(sentinel)

            # Check if process exited with error
            if proc.exitcode != 0:

                    raise RuntimeError(
                        f"Process {proc.name} (PID: {proc.pid}) "
                        f"died with exit code {proc.exitcode}")

            if actor_run_refs:
                import ray
                _, actor_run_refs = ray.wait(actor_run_refs, timeout=5)

    except KeyboardInterrupt:
        logger.info("Received KeyboardInterrupt, shutting down API servers...")
    except Exception as e:
        logger.exception("Exception occurred while running API servers: %s",
                         str(e))
        raise
    finally:
        logger.info("Terminating remaining processes ...")
        api_server_manager.close()
        if coordinator:
            coordinator.close()
        if engine_manager:
            engine_manager.close()


# Note(rob): shutdown function cannot be a bound method,
# else the gc cannot collect the object.
def shutdown(procs: list[BaseProcess]):
    # Shutdown the process.
    for proc in procs:
        if proc.is_alive():
            proc.terminate()

    # Allow 5 seconds for remaining procs to terminate.
    deadline = time.monotonic() + 5
    for proc in procs:
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            break
        if proc.is_alive():
            proc.join(remaining)

    for proc in procs:
        if proc.is_alive() and (pid := proc.pid) is not None:
            kill_process_tree(pid)


def copy_slice(from_tensor: torch.Tensor, to_tensor: torch.Tensor,
               length: int) -> torch.Tensor:
    """
    Copy the first length elements of a tensor into another tensor in a
    non-blocking manner.

    Used to copy pinned CPU tensor data to pre-allocated GPU tensors.

    Returns the sliced target tensor.
    """
    return to_tensor[:length].copy_(from_tensor[:length], non_blocking=True)


