    if url_spec.scheme == "data":
        future = loop.run_in_executor(global_thread_pool,
                                      self._load_data_url, url_spec,
                                      media_io)
        return await future

    if url_spec.scheme == "file":
        future = loop.run_in_executor(global_thread_pool,
                                      self._load_file_url, url_spec,

