def _parse_steptml_invoke(
        action_text: str
) -> tuple[Optional[str], Optional[dict[str, str]]]:
    func_name_match = re.search(r'<steptml:invoke name="([^"]+)">',
                                action_text)
    if not func_name_match:
        return None, None
    func_name = func_name_match.group(1)

    params: dict[str, str] = {}
    param_matches = re.findall(
        r'<steptml:parameter name="([^"]+)">([^<]*)</steptml:parameter>',
        action_text)
    for name, value in param_matches:
        params[name] = value.strip()
    return func_name, params

def _cast_arguments(
    self,
    func_name: str,
    params: dict[str, Any],
    request: ChatCompletionRequest,
) -> dict[str, Any]:
    for tool in request.tools or []:
        if tool.function.name == func_name:
            schema = tool.function.parameters or {}
            properties = schema.get("properties", {})
            for key, value in params.items():
                if not isinstance(value, str):
                    continue
                prop = properties.get(key, {})
                typ = prop.get("type")
                if typ == "string":
                    params[key] = value.strip()
                elif typ == "integer":
                    with contextlib.suppress(ValueError):
                        params[key] = int(value)
                elif typ == "number":
                    with contextlib.suppress(ValueError):
                        params[key] = float(value)
                elif typ == "boolean":
                    lower_val = value.lower()
                    params[key] = lower_val == "true" if lower_val in (
                        "true", "false") else value
                elif typ == "null":
                    params[key] = None if value.lower(

                    ) == "null" else value
            break
    return params

