def _validate_and_reshape_mm_tensor(self, mm_input: NestedTensors,
                                    name: str) -> torch.Tensor:
    if not isinstance(mm_input, (torch.Tensor, list)):
        raise ValueError(f"Incorrect type of {name}. "
                         f"Got type: {type(mm_input)}")
    if isinstance(mm_input, torch.Tensor):
        if mm_input.ndim == 2:
            return mm_input
        if mm_input.ndim == 5:
            return mm_input
        if mm_input.ndim != 3:
            raise ValueError(f"{name} should be 2D or batched 3D tensor. "
                             f"Got ndim: {mm_input.ndim} "
                             f"(shape={mm_input.shape})")
        return torch.concat(list(mm_input))
    elif is_list_of(mm_input, torch.Tensor):
        if all(p.dim() == 4 for p in mm_input) or all(p.dim() == 2
                                                      for p in mm_input):
            return mm_input
    return torch.concat(list(mm_input))

def _parse_and_validate_image_input(
        self, **kwargs: object) -> Optional[KeyeImageInputs]:
    pixel_values = kwargs.pop("pixel_values", None)
    image_embeds = kwargs.pop("image_embeds", None)
    image_grid_thw = kwargs.pop("image_grid_thw", None)

    if pixel_values is None and image_embeds is None:
        return None

    if pixel_values is not None:
        pixel_values = self._validate_and_reshape_mm_tensor(

            vision_return_embed_list=True,
            interpolate_pos_encoding=True,
            sample_indices=sample_indices,
            cu_seqlens=cu_seqlens,
            use_rope=True,
            window_size=-1,
        )
        video_embeds = tuple(self.mlp_AR(video_embeds, video_grid_thw))
        return video_embeds

def _parse_and_validate_multimodal_inputs(self, **kwargs: object) -> dict:
    modalities = {}

    for input_key in kwargs:
        if (input_key in ("pixel_values", "image_embeds")
                and "images" not in modalities):
            modalities["images"] = self._parse_and_validate_image_input(
                **kwargs)
        if (input_key in ("pixel_values_videos", "video_embeds")
                and "videos" not in modalities):
            modalities["videos"] = self._parse_and_validate_video_input(
                **kwargs)

    return modalities

def get_language_model(self) -> torch.nn.Module:
    return self.language_model

def get_multimodal_embeddings(
        self, **kwargs: object) -> Optional[MultiModalEmbeddings]:

    modalities = self._parse_and_validate_multimodal_inputs(**kwargs)
    if not modalities:
        return None

    multimodal_embeddings: tuple[torch.Tensor, ...] = ()

    for modality in modalities:
        if modality == "images":
            image_input = modalities["images"]
            vision_embeddings = self._process_image_input(image_input)
            multimodal_embeddings += vision_embeddings
        if modality == "videos":
            video_input = modalities["videos"]
            video_embeddings = self._process_video_input(video_input)
            multimodal_embeddings += video_embeddings
    return multimodal_embeddings

